//! Config storage migration, step 1: what survives `redb → lanforge.toml → redb`.
//!
//! The db worker renders the live config (redb) into `lanforge.toml` on every flush, and the
//! cut-over to "files are config" makes that file the only source: any field this path drops
//! is lost for good at the cut-over. Each section is tested with **every** field away from its
//! default — the fixture is generated by mutating each JSON leaf of a base value, so a field
//! added later is covered without touching these tests.

use serde::Serialize;
use serde::de::DeserializeOwned;
use serde_json::Value;

use super::ConfigFile;
use crate::api::SystemConfigExport;

/// Candidate replacements for a leaf: the first one the type accepts is kept.
fn candidates(leaf: &Value) -> Vec<Value> {
    match leaf {
        Value::Bool(b) => vec![Value::Bool(!b)],
        Value::Number(n) => {
            if let Some(u) = n.as_u64() {
                vec![(u + 1).into(), u.saturating_sub(1).into()]
            } else if let Some(i) = n.as_i64() {
                vec![(i + 1).into()]
            } else {
                vec![(n.as_f64().unwrap_or(0.0) + 0.5).into()]
            }
        }
        Value::String(s) => {
            let mut out = Vec::new();
            if let Ok(ip) = s.parse::<std::net::Ipv4Addr>() {
                let o = ip.octets();
                out.push(
                    std::net::Ipv4Addr::new(o[0], o[1], o[2], o[3] ^ 1)
                        .to_string()
                        .into(),
                );
            }
            if let Ok(ip) = s.parse::<std::net::Ipv6Addr>() {
                let mut seg = ip.segments();
                seg[7] ^= 1;
                out.push(std::net::Ipv6Addr::from(seg).to_string().into());
            }
            if let Ok(sa) = s.parse::<std::net::SocketAddr>() {
                out.push(
                    std::net::SocketAddr::new(sa.ip(), sa.port() ^ 1)
                        .to_string()
                        .into(),
                );
            }
            out.push(format!("{s}x").into());
            // URLs and other strings ending in a number (`udp://host:53`).
            if let Some(d) = s.chars().last().and_then(|c| c.to_digit(10)) {
                out.push(format!("{}{}", &s[..s.len() - 1], (d + 1) % 10).into());
            }
            out.push("mutated".into());
            // Human durations (RA lifetimes).
            out.push("infinity".into());
            out.push("2h".into());
            out
        }
        Value::Null => vec![
            "mutated".into(),
            7.into(),
            true.into(),
            "10.0.0.7".into(),
            "2001:db8::7".into(),
            "10.0.0.7:53".into(),
            "aa:bb:cc:dd:ee:07".into(),
        ],
        _ => Vec::new(),
    }
}

/// Leaves kept as in the base: moving them makes the fixture itself invalid, not lossy.
const FIXED: &[&str] = &[
    // Only static hosts are config; others are not exported at all.
    "/hosts/0/origin",
    // Must match the answer's type.
    "/dns_rewrites/0/rtype",
    // Import flag, not config.
    "/overwrite",
    // Pinned at `Infinity` in `base()`: the known loss is that value specifically.
    "/ra_prefixes/0/preferred_lifetime",
    "/ra_prefixes/0/valid_lifetime",
];

/// Variant names from serde's "unknown variant `x`, expected one of `A`, `B`" error.
fn enum_variants(err: &str) -> Vec<String> {
    let Some(rest) = err.split("expected ").nth(1) else {
        return Vec::new();
    };
    rest.split('`')
        .skip(1)
        .step_by(2)
        .map(str::to_string)
        .collect()
}

fn leaf_paths(v: &Value, prefix: &str, out: &mut Vec<String>) {
    match v {
        Value::Object(map) => {
            for (k, child) in map {
                leaf_paths(child, &format!("{prefix}/{k}"), out);
            }
        }
        // An empty list has no leaves to move: report it so `base()` gets an entry.
        Value::Array(items) if items.is_empty() => out.push(prefix.to_string()),
        Value::Array(items) => {
            for (i, child) in items.iter().enumerate() {
                leaf_paths(child, &format!("{prefix}/{i}"), out);
            }
        }
        _ => out.push(prefix.to_string()),
    }
}

/// Moves every leaf under `prefix` away from its value where the type allows it. Returns
/// the mutated value and the leaves no candidate fitted (to extend the base by hand).
fn mutate_all<T: Serialize + DeserializeOwned>(base: &T, prefix: &str) -> (T, Vec<String>) {
    let mut json = serde_json::to_value(base).unwrap();
    let mut paths = Vec::new();
    leaf_paths(&json[prefix.trim_start_matches('/')], prefix, &mut paths);
    let mut untouched = Vec::new();
    for path in paths {
        if FIXED.contains(&path.as_str()) {
            continue;
        }
        let original = json.pointer(&path).cloned().unwrap();
        let mut accepted = false;
        let mut cands = candidates(&original);
        let mut i = 0;
        while i < cands.len() {
            let cand = cands[i].clone();
            i += 1;
            *json.pointer_mut(&path).unwrap() = cand.clone();
            match serde_json::from_value::<T>(json.clone()) {
                Ok(t) if serde_json::to_value(&t).unwrap().pointer(&path) == Some(&cand) => {
                    accepted = true;
                    break;
                }
                Ok(_) => {}
                // A unit enum names its variants in the error: try the others.
                Err(e) if i == 1 => cands.extend(
                    enum_variants(&e.to_string())
                        .into_iter()
                        .filter(|v| Value::String(v.clone()) != original)
                        .map(Value::String),
                ),
                Err(_) => {}
            }
        }
        if !accepted {
            *json.pointer_mut(&path).unwrap() = original;
            untouched.push(path);
        }
    }
    (serde_json::from_value(json).unwrap(), untouched)
}

fn through_toml(export: &SystemConfigExport) -> SystemConfigExport {
    let rendered = ConfigFile::from(export).render_full().unwrap();
    let parsed = ConfigFile::parse(&rendered)
        .unwrap_or_else(|e| panic!("rendered TOML does not parse: {e}\n{rendered}"));
    SystemConfigExport::from(&parsed)
}

/// Sorts arrays of named objects by name: TOML tables keyed by name come back in key order,
/// which is not a loss.
fn normalize(v: &mut Value) {
    match v {
        Value::Array(items) => {
            items.iter_mut().for_each(normalize);
            if items
                .iter()
                .all(|i| i.get("name").is_some_and(Value::is_string))
            {
                items.sort_by(|a, b| a["name"].as_str().cmp(&b["name"].as_str()));
            }
        }
        Value::Object(map) => map.values_mut().for_each(normalize),
        _ => {}
    }
}

/// Leaves of `section` that differ after the round trip.
fn lost(section: &str, before: &SystemConfigExport, after: &SystemConfigExport) -> Vec<String> {
    let mut b = serde_json::to_value(before).unwrap()[section].clone();
    let mut a = serde_json::to_value(after).unwrap()[section].clone();
    normalize(&mut b);
    normalize(&mut a);
    let mut paths = Vec::new();
    leaf_paths(&b, "", &mut paths);
    leaf_paths(&a, "", &mut paths);
    paths.sort();
    paths.dedup();
    paths
        .into_iter()
        .filter(|p| b.pointer(p) != a.pointer(p))
        .map(|p| format!("{section}{p}"))
        .collect()
}

/// Mutates `section` of `base` fully and round-trips it. Returns what changed on the way
/// and the leaves the mutation could not move.
fn section_losses(section: &str, base: &SystemConfigExport) -> (Vec<String>, Vec<String>) {
    let (export, untouched) = mutate_all(base, &format!("/{section}"));
    let after = through_toml(&export);
    (lost(section, &export, &after), untouched)
}

/// One entry in every list section, every optional section present: the starting point the
/// mutation moves away from.
fn base() -> SystemConfigExport {
    use lanforge_types::device::Origin;
    use lanforge_types::identifiers::MacAddr;
    use lanforge_types::network::DnsRecordType;
    use lanforge_types::network::dhcp::{DhcpOptionsConfig, Dhcpv4Pool, Dhcpv6Pool};
    use lanforge_types::network::dns::AdblockUrlEntry;
    use lanforge_types::network::dns::adblock::{
        AdblockDbConfig, AdblockRuleAction, AdblockRuleEntry, AdblockSourceFormat, AdblockUrlKind,
        RewriteAnswer, RewriteRule,
    };
    use lanforge_types::network::dns::upstream::UpstreamProtocol;
    use lanforge_types::network::firewall::FirewallConfig;
    use lanforge_types::network::pppoe::PppoeConfig;
    use lanforge_types::network::ra::{DnsslConfig, PrefixLifetime, RAPrefix, RdnssConfig};
    use lanforge_types::network::subnet::DnsReverseResolver;
    use lanforge_types::network::traffic::TrafficConfig;

    use crate::api::devices::HostConfigEntry;
    use crate::api::dns::{AllowlistEntry, DnsUpstreamConfig};

    let export = SystemConfigExport {
        hosts: vec![HostConfigEntry {
            mac: MacAddr::parse("aa:bb:cc:dd:ee:01").unwrap(),
            hostname: "nas".into(),
            v4_fixed: Some("192.168.1.10".parse().unwrap()),
            v6_suffix: Some("::10".parse().unwrap()),
            origin: Origin::Static,
            ignore_dns_log: false,
            ignored_log_domains: vec!["example.org".into()],
        }],
        dns_rewrites: vec![RewriteRule {
            id: None,
            domain: "nas.lan".into(),
            rtype: DnsRecordType::A,
            answer: RewriteAnswer::A("192.168.1.10".parse().unwrap()),
        }],
        dns_upstreams: vec![DnsUpstreamConfig {
            name: Some("quad9".into()),
            addr: "9.9.9.9:853".parse().unwrap(),
            protocol: UpstreamProtocol::Tls,
            domain: Some("dns.quad9.net".into()),
        }],
        dns_adblock_config: AdblockDbConfig::default(),
        dns_adblock_urls: vec![AdblockUrlEntry {
            id: None,
            name: Some("oisd".into()),
            url: "https://big.oisd.nl/".into(),
            kind: AdblockUrlKind::Blocklist,
            format: AdblockSourceFormat::default(),
        }],
        dns_allowlist: vec![AllowlistEntry {
            id: 1,
            domain: "allowed.example".into(),
        }],
        dns_adblock_rules: Some(vec![AdblockRuleEntry {
            id: None,
            name: Some("rule".into()),
            domain: "ads.example".into(),
            action: AdblockRuleAction::Block,
            enabled: true,
        }]),
        api_tokens: None,
        dhcp_v4_pools: Some(vec![Dhcpv4Pool {
            name: Some("lan".into()),
            range_start: "192.168.1.100".parse().unwrap(),
            range_end: "192.168.1.200".parse().unwrap(),
            subnet_mask: Some("255.255.255.0".parse().unwrap()),
            router: Some("192.168.1.1".parse().unwrap()),
            dns_servers: vec!["192.168.1.1".parse().unwrap()],
            lease_time: Some(43200),
            ..Default::default()
        }]),
        dhcp_v6_pools: Some(vec![Dhcpv6Pool {
            name: Some("lan6".into()),
            ..Default::default()
        }]),
        ra_prefixes: Some(vec![RAPrefix {
            valid_lifetime: PrefixLifetime::Infinity,
            preferred_lifetime: PrefixLifetime::Infinity,
            ..RAPrefix::default()
        }]),
        ra_rdnss: Some(vec![RdnssConfig::default()]),
        ra_dnssl: Some(vec![DnsslConfig::default()]),
        pppoe_config: Some(Box::new(PppoeConfig::default())),
        dhcp_options: Some(Box::new(DhcpOptionsConfig::default())),
        dns_reverse_resolvers: Some(vec![DnsReverseResolver {
            subnet: "192.168.1.0/24".parse().unwrap(),
            resolver: "udp://192.168.1.1:53".parse().unwrap(),
        }]),
        firewall_config: Some(Box::new(FirewallConfig::default())),
        traffic_config: Some(Box::new(TrafficConfig::default())),
        system_iface: Some("lan0".into()),
        overwrite: false,
    };
    fill_empty_lists(export)
}

/// Gives every empty list in the fixture one element, so its contents are round-tripped too.
fn fill_empty_lists(export: SystemConfigExport) -> SystemConfigExport {
    let mut json = serde_json::to_value(&export).unwrap();
    let open_port = json["firewall_config"]["zones"][0]["open_ports"][0].clone();
    let port_forward = serde_json::json!({
        "comment": "plex",
        "src_zone": "external",
        "internal_ip": "192.168.1.20",
        "external_port": 32400,
        "internal_port": 32400,
        "protocol": "Tcp",
        "enable_hairpin": true,
    });
    let scalars = [
        "home.lan",
        "192.0.2.123",
        "2001:db8::53",
        "192.168.1.0/24",
        "lan0",
    ];
    let mut paths = Vec::new();
    leaf_paths(&json, "", &mut paths);
    for path in paths {
        if json.pointer(&path) != Some(&Value::Array(Vec::new())) {
            continue;
        }
        let subnet = serde_json::json!({ "addr": "192.168.1.0", "prefix_len": 24 });
        let objects = [open_port.clone(), port_forward.clone(), subnet];
        let candidates = objects.into_iter().chain(scalars.map(Value::from));
        for cand in candidates {
            let filled = Value::Array(vec![cand]);
            *json.pointer_mut(&path).unwrap() = filled.clone();
            if serde_json::from_value::<SystemConfigExport>(json.clone())
                .is_ok_and(|e| serde_json::to_value(e).unwrap().pointer(&path) == Some(&filled))
            {
                break;
            }
            *json.pointer_mut(&path).unwrap() = Value::Array(Vec::new());
        }
    }
    serde_json::from_value(json).unwrap()
}

/// Fields each section loses today on `redb → lanforge.toml → redb`. Migrating a section
/// (config-storage step 2) empties its list; the test then holds it at zero.
const KNOWN_LOSSES: &[(&str, &[&str])] = &[
    (
        "dhcp_options",
        &[
            "/tftp/block_size",
            "/tftp/enabled",
            "/tftp/listen_addr",
            "/tftp/max_retries",
            "/tftp/root_dir",
            "/tftp/timeout",
            "/v4/ntp_servers/0",
            "/v4/ntp_servers/1",
            "/v4/tftp_server",
            "/v6/boot_file",
            "/v6/ntp_servers/0",
            "/v6/ntp_servers/1",
        ],
    ),
    (
        "dhcp_v4_pools",
        &[
            "/0/boot_file",
            "/0/domain_name",
            "/0/ntp_servers",
            "/0/ntp_servers/0",
            "/0/search_domains",
            "/0/search_domains/0",
            "/0/tftp_server",
        ],
    ),
    (
        "dhcp_v6_pools",
        &[
            "/0/address",
            "/0/boot_file",
            "/0/ntp_servers",
            "/0/ntp_servers/0",
            "/0/search_domains",
            "/0/search_domains/0",
        ],
    ),
    ("dns_adblock_config", &[]),
    ("dns_adblock_rules", &["/0/id", "/0/name"]),
    ("dns_adblock_urls", &["/0/id"]),
    ("dns_allowlist", &["/0/id"]),
    // Not in the TOML at all.
    (
        "dns_reverse_resolvers",
        &["", "/0/resolver", "/0/subnet/addr", "/0/subnet/prefix_len"],
    ),
    ("dns_rewrites", &["/0/id"]),
    ("dns_upstreams", &[]),
    (
        "firewall_config",
        &[
            "/zones/0/open_ports/0/comment",
            "/zones/1/open_ports/0/comment",
            "/zones/1/open_ports/1/comment",
            "/zones/1/open_ports/2/comment",
            "/zones/1/open_ports/3/comment",
            "/zones/1/open_ports/4/comment",
            "/zones/1/open_ports/5/comment",
            "/zones/2/open_ports/0/comment",
        ],
    ),
    (
        "hosts",
        &["/0/ignored_log_domains", "/0/ignored_log_domains/0"],
    ),
    // Migrated: the file holds `PppoeConfig` itself.
    ("pppoe_config", &[]),
    ("ra_dnssl", &[]),
    // `infinity` lifetimes are rendered as nothing and read back as the defaults.
    (
        "ra_prefixes",
        &[
            "/0/preferred_lifetime",
            "/0/router_addr",
            "/0/valid_lifetime",
        ],
    ),
    ("ra_rdnss", &[]),
    ("system_iface", &[]),
    (
        "traffic_config",
        &[
            "/sqm/diffserv",
            "/sqm/ingress_device",
            "/sqm/overhead",
            "/sqm/per_host_isolation",
            "/sqm/raw_cake_args",
            "/sqm/rtt_ms",
        ],
    ),
];

#[test]
fn every_config_section_is_covered() {
    let base = serde_json::to_value(base()).unwrap();
    let sections: Vec<&str> = base
        .as_object()
        .unwrap()
        .keys()
        .map(String::as_str)
        .filter(|k| !matches!(*k, "api_tokens" | "overwrite"))
        .collect();
    let known: Vec<&str> = KNOWN_LOSSES.iter().map(|(s, _)| *s).collect();
    assert_eq!(sections, known, "a section was added or renamed: list it");
}

#[test]
fn every_field_is_moved_by_the_fixture() {
    let untouched: Vec<String> = KNOWN_LOSSES
        .iter()
        .flat_map(|(section, _)| section_losses(section, &base()).1)
        .collect();
    assert!(
        untouched.is_empty(),
        "extend `base()` so these move: {untouched:#?}"
    );
}

#[test]
fn round_trip_losses_match_the_known_list() {
    let mut report = String::new();
    for (section, known) in KNOWN_LOSSES {
        let (lost, _) = section_losses(section, &base());
        let expected: Vec<String> = known.iter().map(|p| format!("{section}{p}")).collect();
        if lost != expected {
            report.push_str(&format!(
                "{section}:\n  lost now: {lost:?}\n  known:    {expected:?}\n"
            ));
        }
    }
    assert!(
        report.is_empty(),
        "round trip changed — a migrated section must drop its entries, a new loss is a bug:\n{report}"
    );
}
